def design(feats):
    import numpy as np
    from scipy import stats
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float)
    n, p = X.shape; ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1))
    if len(labs) > 1:
        st = np.array(feats.stratum)
        S = np.column_stack([S] + [(st == l).astype(float) for l in labs[1:]])
    def ll(M):
        b = np.zeros(M.shape[1])
        for _ in range(30):
            eta = np.clip(M @ b, -30, 30); mu = 1 / (1 + np.exp(-eta))
            w = mu * (1 - mu) + 1e-9
            H = M.T @ (M * w[:, None]) + 1e-6 * np.eye(M.shape[1])
            step = np.linalg.solve(H, M.T @ (y - mu)); b += step
            if np.max(np.abs(step)) < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(M @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    def design_mat(sel, extra=None):
        cols = [S] + [X[:, [j]] for j in sel]
        if extra is not None: cols.append(extra[:, None])
        return np.column_stack(cols)
    R = np.corrcoef(X, rowvar=False)
    sel = []; base = ll(S)
    while len(sel) < MAX_DRIVERS:
        alpha = 0.05 / p if not sel else 0.01 / p
        best, bj = None, None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel): continue
            l1 = ll(design_mat(sel + [j]))
            if best is None or l1 > best: best, bj = l1, j
        if bj is None or stats.chi2.sf(2 * (best - base), 1) > alpha: break
        sel.append(bj); base = best
    changed = True
    while changed and len(sel) > 1:
        changed = False; full = ll(design_mat(sel))
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (full - ll(design_mat(rest))), 1) > 0.01 / p:
                sel = rest; changed = True; break
    full = ll(design_mat(sel)); prods = []
    npairs = p * (p + 1) / 2
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b})
            l0 = ll(design_mat(mains)) if mains != sorted(sel) else full
            z = X[:, a] * X[:, b]
            l1 = ll(design_mat(mains, z))
            pv = stats.chi2.sf(2 * (l1 - l0), 1)
            if pv < 0.01 / npairs: prods.append((pv, a, b))
    prods = sorted(prods)[:2]
    drivers = [ids[j] for j in sel]
    for _, a, b in prods:
        for j in (a, b):
            if ids[j] not in drivers: drivers.append(ids[j])
    drivers = drivers[:MAX_DRIVERS]
    colset = list(dict.fromkeys([ids[j] for j in sel] + [ids[j] for _, a, b in prods for j in (a, b)]))
    return Design(drivers=tuple(drivers), columns=tuple(colset),
                  products=tuple((ids[a], ids[b]) for _, a, b in prods), loadings={})

